import json
import sys


def run_tx(state, ops):
    """Simulate one atomic transaction. Return the new state dict, or None if
    any observation (get / cas success / scan result) does not match."""
    d = dict(state)
    for op in ops:
        kind = op[0]
        if kind == 'get':
            if d.get(op[1]) != op[2]:
                return None
        elif kind == 'put':
            d[op[1]] = op[2]
        elif kind == 'del':
            d.pop(op[1], None)
        elif kind == 'cas':
            # op = [cas, key, expected_old, new_value, expected_success]
            ok = d.get(op[1]) == op[2]
            if ok != op[4]:
                return None
            if ok:
                if op[3] is None:
                    d.pop(op[1], None)
                else:
                    d[op[1]] = op[3]
        else:  # scan: [scan, low, high, expected_pairs]
            low, high, expected = op[1], op[2], op[3]
            got = [[k, v] for k, v in sorted(d.items()) if low <= k < high]
            if got != expected:
                return None
    return d


def solve(request):
    initial = request['initial']
    final = request['final']
    txs = request['transactions']
    n = len(txs)

    # Precedence: if A.end <= B.start then A must occur before B.
    # (This relation is always acyclic since start < end.)
    preds = [0] * n
    for i in range(n):
        ei = txs[i]['end']
        for j in range(n):
            if i != j and ei <= txs[j]['start']:
                preds[j] |= 1 << i

    ids = [t['id'] for t in txs]
    ops_list = [t['ops'] for t in txs]

    # Per transaction, the last write effect on each key:
    #   key -> (must_write, frozenset of possible resulting values; None = absent)
    # A put/del always writes; a cas as the last write to the key may fail,
    # so it is an optional write.
    effects = []
    for t in txs:
        last = {}
        for op in t['ops']:
            k = op[0]
            if k == 'put':
                last[op[1]] = (True, frozenset((op[2],)))
            elif k == 'del':
                last[op[1]] = (True, frozenset((None,)))
            elif k == 'cas':
                last[op[1]] = (False, frozenset((op[3],)))
        effects.append(last)

    full = (1 << n) - 1
    failed = set()

    def final_feasible(d, mask):
        """Cheap necessary condition: per key (independently), can the final
        value still be produced by the remaining transactions?"""
        stats = {}
        for i in range(n):
            if (mask >> i) & 1:
                continue
            for k, (mw, vals) in effects[i].items():
                st = stats.get(k)
                if st is None:
                    st = stats[k] = [False, set(), set()]
                if mw:
                    st[0] = True
                    st[1] |= vals
                else:
                    st[2] |= vals
        for k in set(d) | set(final) | set(stats):
            fv = final.get(k)
            st = stats.get(k)
            if st is None:
                if d.get(k) != fv:
                    return False
            else:
                any_forced, forced_vals, opt_vals = st
                ach = forced_vals | opt_vals
                if not any_forced:
                    ach = ach | {d.get(k)}
                if fv not in ach:
                    return False
        return True

    def bt(mask, d):
        if mask == full:
            return [] if d == final else None
        fkey = (mask, tuple(sorted(d.items())))
        if fkey in failed:
            return None
        if not final_feasible(d, mask):
            failed.add(fkey)
            return None
        for i in range(n):
            b = 1 << i
            if (mask & b) or (preds[i] & ~mask):
                continue
            nd = run_tx(d, ops_list[i])
            if nd is None:
                continue
            r = bt(mask | b, nd)
            if r is not None:
                return [ids[i]] + r
        failed.add(fkey)
        return None

    return {'order': bt(0, dict(initial))}


if __name__ == '__main__':
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))) + '\n')
        out.flush()
