import json, random, itertools, sys
sys.path.insert(0, '/app')
from public_contract import valid_history

KEYS = ['a','b','c','d','e','f']

def run_tx(d, ops):
    d = dict(d)
    for op in ops:
        k = op[0]
        if k == 'get':
            if d.get(op[1]) != op[2]: return None
        elif k == 'put': d[op[1]] = op[2]
        elif k == 'del': d.pop(op[1], None)
        elif k == 'cas':
            ok = d.get(op[1]) == op[2]
            if ok != op[4]: return None
            if ok:
                if op[3] is None: d.pop(op[1], None)
                else: d[op[1]] = op[3]
        else:
            got = [[kk,vv] for kk,vv in sorted(d.items()) if op[1]<=kk<op[2]]
            if got != op[3]: return None
    return d

def rand_ops(rng, keys):
    m = rng.randint(1,5)
    ops = []
    for _ in range(m):
        kind = rng.choice(['get','put','del','cas','scan'])
        if kind == 'get':
            ops.append(['get', rng.choice(keys), None])  # placeholder
        elif kind == 'put':
            ops.append(['put', rng.choice(keys), rng.randint(-9,9)])
        elif kind == 'del':
            ops.append(['del', rng.choice(keys)])
        elif kind == 'cas':
            old = rng.choice([None, rng.randint(-9,9)])
            new = rng.choice([None, rng.randint(-9,9)])
            ops.append(['cas', rng.choice(keys), old, new, None])
        else:
            ks = sorted(rng.sample(keys, 2))
            ops.append(['scan', ks[0], ks[1], None])
    return ops

def fill_observations(ops, d):
    """Execute ops against state d, filling in observed values (None placeholders).
    For cas, the expected_old is fixed but expected_success placeholder gets filled.
    Returns new state. Assumes the filled observations match (we construct them to)."""
    d = dict(d)
    out = []
    for op in ops:
        k = op[0]
        if k == 'get':
            out.append(['get', op[1], d.get(op[1])])
        elif k == 'put':
            d[op[1]] = op[2]; out.append(op)
        elif k == 'del':
            d.pop(op[1], None); out.append(op)
        elif k == 'cas':
            ok = d.get(op[1]) == op[2]
            if ok:
                if op[3] is None: d.pop(op[1], None)
                else: d[op[1]] = op[3]
            out.append(['cas', op[1], op[2], op[3], ok])
        else:
            got = [[kk,vv] for kk,vv in sorted(d.items()) if op[1]<=kk<op[2]]
            out.append(['scan', op[1], op[2], got])
    return out, d

def gen_case(rng, n_tx=None, n_keys=None, valid=True):
    nkeys = n_keys if n_keys is not None else rng.randint(1,6)
    keys = sorted(rng.sample(KEYS, nkeys))
    n = n_tx if n_tx is not None else rng.randint(0,10)
    txs = []
    for i in range(n):
        s = rng.randint(0, 20)
        e = s + rng.randint(1, 8)
        txs.append({'id': f't{i}', 'start': s, 'end': e, 'ops': rand_ops(rng, keys)})
    # initial map
    init = {k: rng.randint(-9,9) for k in keys if rng.random() < 0.4}
    # choose a random valid linearization consistent with precedence
    preds = {i: set() for i in range(n)}
    for i in range(n):
        for j in range(n):
            if i != j and txs[i]['end'] <= txs[j]['start']:
                preds[j].add(i)
    order = []
    avail = [i for i in range(n) if not preds[i]]
    placed = set()
    while len(order) < n:
        choices = [i for i in range(n) if i not in placed and preds[i] <= placed]
        i = rng.choice(choices)
        order.append(i); placed.add(i)
    # execute in that order, filling observations
    d = dict(init)
    for i in order:
        txs[i]['ops'], d = fill_observations(txs[i]['ops'], d)
    fin = d
    req = {'initial': init, 'final': fin, 'transactions': txs}
    if not valid:
        # mutate: corrupt one observation or the final map
        which = rng.random()
        if which < 0.5 and n > 0:
            t = rng.choice(txs)
            opi = rng.randrange(len(t['ops']))
            op = t['ops'][opi]
            if op[0] == 'get':
                op[2] = rng.randint(-9,9) if op[2] is None else None
            elif op[0] == 'cas':
                op[4] = not op[4]
            elif op[0] == 'scan':
                op[3] = op[3] + [[rng.choice(keys), rng.randint(-9,9)]]
            else:
                op[0] = op[0]
        else:
            fin = dict(fin)
            k = rng.choice(keys)
            if rng.random() < 0.5: fin[k] = rng.randint(-9,9)
            else: fin.pop(k, None)
            req['final'] = fin
    return req

def brute_force_sat(req):
    n = len(req['transactions'])
    for perm in itertools.permutations(range(n)):
        order = [req['transactions'][i]['id'] for i in perm]
        if valid_history(req, order):
            return True
    return False
